UPDATE sku_stock
SET lock_stock = lock_stock - #{goodsQuantity},
    stock      = stock - #{goodsQuantity}
WHERE id = #{goodsSkuId}
  AND stock - #{goodsQuantity} >= 0
  AND lock_stock - #{goodsQuantity} >= 0

UPDATE sku_stock
SET lock_stock = lock_stock - #{goodsQuantity}
WHERE id = #{goodsSkuId}
  AND lock_stock - #{goodsQuantity} >= 0

UPDATE sku_stock
SET stock = stock + #{goodsQuantity}
WHERE id = #{goodsSkuId}

UPDATE sku_stock
SET sale = sale + #{goodsQuantity}
WHERE id = #{goodsSkuId}
